const inp = $input.first().json;
const reviewer = (inp.reviewer_user_id || '2521617').toString();
const tcomment = (inp.triggering_comment_text || '').toString();
const prompt = 'Czy to zadanie wymaga aktualnych informacji z internetu (ceny, biezace wydarzenia, kursy walut, specyfikacje produktow, swieze fakty spoza wiedzy modelu), aby je dobrze wykonac? Odpowiedz wylacznie jednym slowem: TAK lub NIE.\n\nZADANIE:\n' + (inp.task_name || '') + '\n' + (inp.task_description || '') + (tcomment ? ('\n\nWIADOMOSC UZYTKOWNIKA:\n' + tcomment) : '');
return [{ json: {
  prompt: prompt,
  model_override: 'haxe-haiku-4-5-direct',
  impact: inp.impact || '',
  clickup_task_id: inp.clickup_task_id || '',
  triggered_by: inp.triggered_by || 'explicit_command',
  invocation_type: inp.invocation_type || 'explicit',
  caller_user_id: reviewer,
  process_type: inp.process_type || ''
} }];

const inp = $('When Called').first().json;
const reviewer = (inp.reviewer_user_id || '2521617').toString();
const primary = $('Pick Primary').first().json || {};
const litellm_model = primary.litellm_model || 'haxe-sonnet-4-6-direct';
const max_tokens = (primary.max_tokens != null) ? Number(primary.max_tokens) : 4000;
const temperature = (primary.temperature != null && primary.temperature !== '') ? Number(primary.temperature) : null;
let fb = null; try { fb = $('Resolve Lower Fallback').first().json; } catch (e) {}
const fallback_model = (fb && fb.floor !== true && fb.litellm_model) ? fb.litellm_model : '';
let rp = null; try { const p = $('Lookup Research Params').first().json; if (p && p.max_research_rounds != null) rp = p; } catch(e) {}
const max_research_rounds = (rp && rp.max_research_rounds != null) ? Number(rp.max_research_rounds) : 3;
const tavily_max_results = (rp && rp.tavily_max_results != null) ? Number(rp.tavily_max_results) : 5;
const tcomment = (inp.triggering_comment_text || '').toString();
const userPrompt = 'Jestes asystentem researchu. Zbierz z internetu aktualne, zewnetrzne informacje potrzebne do wykonania ponizszego zadania (np. ceny, kursy, specyfikacje, biezace fakty). Wykonaj potrzebne wyszukiwania, a nastepnie zwroc ZWIEZLE ustalenia (fakty + liczby), bez wykonywania samego zadania. NIE umieszczaj w zapytaniach danych osobowych (nazwiska, e-maile, numery zamowien).\n\nZADANIE:\n' + (inp.task_name || '') + '\n' + (inp.task_description || '') + (tcomment ? ('\n\nWIADOMOSC UZYTKOWNIKA:\n' + tcomment) : '');
const messages = JSON.stringify([{ role: 'user', content: userPrompt }]);
return [{ json: {
  litellm_model: litellm_model,
  messages: messages,
  max_tokens: max_tokens,
  temperature: temperature,
  fallback_model: fallback_model,
  acc_fell_back: false,
  depth: 0,
  max_depth: max_research_rounds,
  acc_in: 0, acc_out: 0, acc_usd: 0, acc_searches: 0,
  sources: '[]',
  tavily_max_results: tavily_max_results,
  calls: '[]',
  clickup_task_id: inp.clickup_task_id || '',
  caller_user_id: reviewer,
  process_type: inp.process_type || '',
  triggered_by: inp.triggered_by || 'explicit_command',
  invocation_type: inp.invocation_type || 'explicit',
  impact: inp.impact || ''
} }];

let web_findings = '', web_sources = [];
let rw = null;
const src = $input.first() ? $input.first().json : null;
if (src && (src.completion !== undefined || src.sources !== undefined)) { rw = src; }
if (!rw) { try { rw = $('Call Research the web').first().json; } catch (e) {} }
if (rw) { web_findings = rw.completion || ''; web_sources = rw.sources || []; }
return [{ json: { web_findings: web_findings, web_sources: web_sources } }];

const low = $('Resolve Lower Primary').first().json || {};
const taskRow = $('Lookup Research Routing').first().json || {};
let primary;
if (low && low.floor !== true && low.litellm_model) {
  primary = { impact: low.impact, litellm_model: low.litellm_model, max_tokens: (low.max_tokens != null ? Number(low.max_tokens) : null), temperature: (low.temperature != null && low.temperature !== '' ? Number(low.temperature) : null) };
} else {
  primary = { impact: (taskRow.impact || 'Niski'), litellm_model: (taskRow.litellm_model || 'haxe-haiku-4-5-direct'), max_tokens: (taskRow.max_tokens != null ? Number(taskRow.max_tokens) : 8000), temperature: (taskRow.temperature != null && taskRow.temperature !== '' ? Number(taskRow.temperature) : null) };
}
return [{ json: primary }];
